"""Rebuild SUPABASE_MANUAL_SETUP.sql (all migrations, in order, as one script for a brand-new database).

Usage: python scripts/build_manual_setup.py [--check]
--check exits non-zero if the committed file is out of date (the test-suite runs this).
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HEADER = """-- ============================================================================
-- VORA: complete database setup for a COMPLETELY NEW Supabase project.
-- GENERATED by scripts/build_manual_setup.py from migrations/0001..{last}. Do not edit by hand.
--
-- How to run: Supabase Dashboard -> SQL Editor -> New query -> paste this whole file -> Run.
-- Run it ONCE on an empty database. Afterwards run SUPABASE_VERIFICATION.sql.
-- Existing databases must use `python scripts/apply_migrations.py` instead (it applies only what is missing).
-- No demo users, customers or documents are created. Create the first superadmin with scripts/manage_users.py.
-- ============================================================================
"""


def build():
    files = sorted((ROOT / 'migrations').glob('[0-9][0-9][0-9][0-9]_*.sql'))
    parts = [HEADER.format(last=files[-1].name[:4])]
    for f in files:
        parts.append(f'\n-- ---------------------------------------------------------------------------\n-- {f.name}\n-- ---------------------------------------------------------------------------\n')
        parts.append(f.read_text().rstrip() + '\n')
    parts.append("""
-- Record the applied migrations so scripts/apply_migrations.py recognises this database.
CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, sha256 text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE schema_migrations ENABLE ROW LEVEL SECURITY;
""")
    import hashlib
    values = ',\n  '.join(f"('{f.name}', '{hashlib.sha256(f.read_bytes()).hexdigest()}')" for f in files)
    parts.append(f'INSERT INTO schema_migrations (name, sha256) VALUES\n  {values}\nON CONFLICT (name) DO NOTHING;\n')
    return ''.join(parts)


if __name__ == '__main__':
    target = ROOT / 'SUPABASE_MANUAL_SETUP.sql'
    text = build()
    if '--check' in sys.argv:
        sys.exit(0 if target.exists() and target.read_text() == text else 'SUPABASE_MANUAL_SETUP.sql is out of date: run scripts/build_manual_setup.py')
    target.write_text(text)
    print(f'wrote {target.name} ({len(text.splitlines())} lines)')
